import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { Mission, MissionsService } from '../../api';

/** Status filter choices for the mission list (REQ-ML-1). `all` shows every mission. */
export type StatusFilter = 'all' | 'open' | 'done';

@Component({
  selector: 'app-mission-list',
  templateUrl: './mission-list.html',
  styleUrl: './mission-list.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MissionList {
  private readonly missionsApi = inject(MissionsService);

  /** `undefined` until the first response lands; the template shows a loading row until then. Fetched once. */
  protected readonly missions = toSignal(this.missionsApi.listMissions());

  /** Options rendered by the filter control, in display order. */
  protected readonly filterOptions: ReadonlyArray<{ value: StatusFilter; label: string }> = [
    { value: 'all', label: 'All' },
    { value: 'open', label: 'Open' },
    { value: 'done', label: 'Done' },
  ];

  /** Currently selected status filter; "All" on first render. */
  protected readonly filter = signal<StatusFilter>('all');

  /** Missions matching the selected filter, in API order. Derived locally; never re-fetches. */
  protected readonly visible = computed<Mission[]>(() => {
    const list = this.missions() ?? [];
    const filter = this.filter();
    return filter === 'all' ? list : list.filter((mission) => mission.status === filter);
  });

  protected onFilterChange(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    if (value === 'all' || value === 'open' || value === 'done') {
      this.filter.set(value);
    }
  }
}

@let list = missions();
@if (list === undefined) {
  <p class="loading" role="status">Loading missions…</p>
} @else if (list.length === 0) {
  <p class="empty">No missions on the board.</p>
} @else {
  @let shown = visible();
  <div class="toolbar">
    <label class="filter">
      <span class="filter-label">Status</span>
      <select class="status-filter" (change)="onFilterChange($event)">
        @for (option of filterOptions; track option.value) {
          <option [value]="option.value" [selected]="option.value === filter()">{{ option.label }}</option>
        }
      </select>
    </label>
    <p class="count" role="status">Showing {{ shown.length }} of {{ list.length }} missions</p>
  </div>
  @if (shown.length === 0) {
    <p class="no-match">No missions match this filter.</p>
  } @else {
    <ul class="missions">
      @for (mission of shown; track mission.id) {
        <li class="mission" [class.done]="mission.status === 'done'">
          <span class="priority" [attr.aria-label]="'priority ' + mission.priority">P{{ mission.priority }}</span>
          <span class="title">{{ mission.title }}</span>
          <span class="status">{{ mission.status }}</span>
        </li>
      }
    </ul>
  }
}

