1	import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { Mission, MissionsService } from '../../api';
4	
5	/** Status filter choices for the mission list (REQ-ML-1). `all` shows every mission. */
6	export type StatusFilter = 'all' | 'open' | 'done';
7	
8	@Component({
9	  selector: 'app-mission-list',
10	  templateUrl: './mission-list.html',
11	  styleUrl: './mission-list.css',
12	  changeDetection: ChangeDetectionStrategy.OnPush,
13	})
14	export class MissionList {
15	  private readonly missionsApi = inject(MissionsService);
16	
17	  /** `undefined` until the first response lands; the template shows a loading row until then. Fetched once. */
18	  protected readonly missions = toSignal(this.missionsApi.listMissions());
19	
20	  /** Options rendered by the filter control, in display order. */
21	  protected readonly filterOptions: ReadonlyArray<{ value: StatusFilter; label: string }> = [
22	    { value: 'all', label: 'All' },
23	    { value: 'open', label: 'Open' },
24	    { value: 'done', label: 'Done' },
25	  ];
26	
27	  /** Currently selected status filter; "All" on first render. */
28	  protected readonly filter = signal<StatusFilter>('all');
29	
30	  /** Missions matching the selected filter, in API order. Derived locally; never re-fetches. */
31	  protected readonly visible = computed<Mission[]>(() => {
32	    const list = this.missions() ?? [];
33	    const filter = this.filter();
34	    return filter === 'all' ? list : list.filter((mission) => mission.status === filter);
35	  });
36	
37	  protected onFilterChange(event: Event): void {
38	    const value = (event.target as HTMLSelectElement).value;
39	    if (value === 'all' || value === 'open' || value === 'done') {
40	      this.filter.set(value);
41	    }
42	  }
43	}
