  describe('status filter (REQ-ML-1)', () => {
    let el: HTMLElement;

    function select(): HTMLSelectElement {
      return el.querySelector('select.status-filter') as HTMLSelectElement;
    }
    function choose(value: 'all' | 'open' | 'done'): void {
      const s = select();
      s.value = value;
      s.dispatchEvent(new Event('change'));
      fixture.detectChanges();
    }
    function titles(): string[] {
      return Array.from(el.querySelectorAll('li.mission .title')).map((t) => t.textContent?.trim() ?? '');
    }
    function count(): string {
      return el.querySelector('p.count')?.textContent?.trim() ?? '';
    }

    beforeEach(async () => {
      el = fixture.nativeElement as HTMLElement;
      await fixture.whenStable();
    });

    it('renders one filter control with exactly All, Open, Done options, All selected first (AC1)', () => {
      respond(MISSIONS);
      expect(el.querySelectorAll('select.status-filter').length).toBe(1);
      const options = Array.from(select().options);
      expect(options.map((o) => o.textContent?.trim())).toEqual(['All', 'Open', 'Done']);
      expect(select().value).toBe('all');
      expect(options[0].selected).toBe(true);
    });

    it('lists every mission in API order with All selected (AC2)', () => {
      respond(MISSIONS);
      expect(titles()).toEqual(['Calibrate the dish', 'Rotate the launch codes', 'Play tic-tac-toe']);
    });

    it('lists only open missions, in API order, when Open is selected (AC3)', () => {
      respond(MISSIONS);
      choose('open');
      expect(titles()).toEqual(['Calibrate the dish', 'Play tic-tac-toe']);
    });

    it('lists only done missions when Done is selected (AC3)', () => {
      respond(MISSIONS);
      choose('done');
      expect(titles()).toEqual(['Rotate the launch codes']);
    });

    it('returns to the full list when switching back to All (AC2, AC3)', () => {
      respond(MISSIONS);
      choose('done');
      choose('all');
      expect(titles().length).toBe(3);
    });

    it('shows "Showing N of M missions" for each filter (AC4)', () => {
      respond(MISSIONS);
      expect(count()).toBe('Showing 3 of 3 missions');
      choose('open');
      expect(count()).toBe('Showing 2 of 3 missions');
      choose('done');
      expect(count()).toBe('Showing 1 of 3 missions');
    });

    it('shows the no-match text and a zero count when the filter matches nothing (AC5)', () => {
      respond([MISSIONS[0], MISSIONS[2]]);
      choose('done');
      expect(el.querySelector('p.no-match')?.textContent?.trim()).toBe('No missions match this filter.');
      expect(el.querySelectorAll('li.mission').length).toBe(0);
      expect(count()).toBe('Showing 0 of 2 missions');
    });

    it('shows the empty-state text and no filter control for an empty array (AC6)', () => {
      respond([]);
      expect(el.querySelector('p.empty')?.textContent?.trim()).toBe('No missions on the board.');
      expect(el.querySelector('select.status-filter')).toBeNull();
      expect(el.querySelector('p.count')).toBeNull();
      expect(el.querySelector('p.no-match')).toBeNull();
    });

    it('sends no new HTTP request when the filter changes (AC7)', () => {
      respond(MISSIONS);
      choose('open');
      choose('done');
      choose('all');
      http.expectNone('/api/missions');
    });
  });
'''
